set -u
ROOT=$(mktemp -d); cp -r "$1"/. "$ROOT"/ 2>/dev/null; cd "$ROOT"
export GOPROXY=off GOFLAGS=-mod=mod GOWORK=off
cat > go.mod <<'G'
// generated by gtr from gtr.json — edit gtr.json or run `gtr sync`
// gtr:hash sha256:PLACEHOLDER

module app

go 1.22

require (
	orm v0.1.0
	orm-mysql v0.1.0
)

require github.com/go-sql-driver/mysql v1.10.0 // indirect

replace orm => ./gtr_modules/orm

replace orm-mysql => ./gtr_modules/orm-mysql

replace github.com/go-sql-driver/mysql => ./gtr_modules/.go/github.com/go-sql-driver/mysql@v1.10.0
G
cp go.mod /tmp/gm2; go mod tidy && diff /tmp/gm2 go.mod && echo "TIDY: no-op, canonical format found"
echo "--- absolute path in replace (store instead of gtr_modules)"
sed -i "s#=> ./gtr_modules/orm\$#=> $ROOT/gtr_modules/orm#" go.mod; go build -o /dev/null . && echo "absolute replace ok"
echo "--- what go get does if the developer adds a dependency manually (GOPROXY=off)"
go get example.com/x@v1.0.0 2>&1 | head -2
